// Die Word-Vorlage des Mandanten. Gesucht wird von innen nach aussen:
// erst die der eigenen Gesellschaft, sonst die des Mandanten, jeweils die
// hoechste aktive Version.
//
// KEIN eingebauter Ersatztext. Ein Vertragsmuster, das niemand geprueft
// hat, wird benutzt, als waere es geprueft — CLAUDE.md verbietet genau
// das ("Vertragsmuster nie ungeprueft als rechtssicher bezeichnen").
// Fehlt die Vorlage, sagt die Anwendung das und nennt den Weg dorthin,
// statt etwas Erfundenes auszugeben.
async function immoVertragsvorlage(art, eingebaut) {
  const bezeichnung = {
    maklervertrag: "Maklervertrag", vollmacht: "Vollmacht",
    objektnachweis: "Objektnachweis", reservierung: "Reservierung"
  }[art] || art;
  try {
    const { data } = await window._sb.from("vertragsvorlagen")
      .select("storage_pfad, gesellschaft_id, version")
      .eq("art", art).eq("aktiv", true)
      .order("version", { ascending: false });
    const treffer = (data || []);
    const eigene = window.IMMO_GESELLSCHAFT_ID
      ? treffer.find((v) => v.gesellschaft_id === window.IMMO_GESELLSCHAFT_ID)
      : null;
    const gewaehlt = eigene || treffer.find((v) => !v.gesellschaft_id) || null;
    if (gewaehlt) {
      const { data: datei, error } = await window._sb.storage
        .from("vertragsvorlagen").download(gewaehlt.storage_pfad);
      if (error) throw error;
      if (datei) return datei;
    }
  } catch (f) {
    console.warn("Vertragsvorlage konnte nicht geladen werden:", f && f.message || f);
  }
  if (eingebaut) return base64ToBlob(eingebaut);
  throw new Error("Für „" + bezeichnung + "“ ist keine Vorlage hinterlegt. "
    + "Eine Word-Datei lädt hoch, wer den Admin-Bereich darf: "
    + "Einstellungen → Vertragsvorlagen.");
}

// Eine fertige Datei zum Herunterladen anbieten.
function immoDateiAnbieten(bytes, name, endung) {
  const typ = endung === "pdf" ? "application/pdf"
    : "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
  const blob = new Blob([bytes], { type: typ });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

// Warnungen aus der Erzeugung sichtbar machen. Ein Wert, der auf der Anlage
// gelandet ist, oder eine Markierung, die ins Leere zeigt, darf nicht still
// bleiben — sonst unterschreibt jemand ein Dokument mit einer leeren Stelle.
function immoVorlageWarnungen(warnungen) {
  if (warnungen && warnungen.length) {
    window.alert("Hinweis zur Vorlage:\n\n" + warnungen.join("\n"));
  }
}

async function fillMaklervertrag(e) {
  // Seit dem 28.09.2026 kommt der Inhalt aus den Stellen, die der Makler in
  // seiner eigenen Vorlage markiert hat (fork_24, fork_25).
  //
  // Der alte Weg suchte woertliche Saetze aus EINEM Mustervertrag der
  // Vorlage und ersetzte sie — den Namen der Vertragsparteien, ihre
  // Strasse, ihren Ort. Fuer die Vorlage eines anderen Maklers traf davon
  // nichts, und das Dokument kam unveraendert heraus, ohne dass es jemand
  // gemerkt haette.
  // Im Quelltext standen dafuer Namen, Anschriften und Ausweisnummern
  // echter Vertragsparteien; die sind damit ebenfalls weg.
  const firma = STANDORTE[e.standort || "musterstadt"] || {};
  const { bytes, endung, warnungen } = await immoVorlageFuellen("maklervertrag", e, firma);

  let p = "";
  if ((e.verkaeufer_typ === "erben" || e.verkaeufer_typ === "mehrere")
      && Array.isArray(e.erben) && e.erben.length > 0) {
    p = e.erben.map((x) => {
      const t = String(x.name || "").trim().split(/\s+/);
      return t[t.length - 1] || "";
    }).filter(Boolean).join("+");
  } else if (e.verkaeufer_typ === "firma") {
    p = e.verkaeufer_name || "";
  } else {
    const t = String(e.verkaeufer_name || "").trim();
    if (t) { const w = t.split(/\s+/); p = w[w.length - 1] || ""; }
  }
  if (!p) p = "Verkaeufer";

  immoDateiAnbieten(bytes, `Maklervertrag_${fileObjekt(e)}_${fileSafe(p)}.${endung}`, endung);
  immoVorlageWarnungen(warnungen);
}

// Ein Block aus N Beteiligten — dieselbe Form wie buildVerkaeuferBlock, nur
// ohne Bindung an die Feldnamen des Maklervertrags. Der Mietvertrag fuehrt
// zwei solche Gruppen: Vermieter und Mieter koennen beide Eheleute oder eine
// Erbengemeinschaft sein.
function immoBeteiligtenBlock(typ, name, strasse, plz, ort, weitere) {
  const liste = Array.isArray(weitere) ? weitere.filter((p) => p && (p.name || p.strasse)) : [];
  if ((typ === "erben" || typ === "mehrere") && liste.length > 0) {
    const zeilen = typ === "erben" ? ["Erbengemeinschaft"] : [];
    liste.forEach((p, i) => {
      if (zeilen.length > 0) zeilen.push("");
      zeilen.push(typ === "erben" ? `Erbe ${i + 1}: ${p.name || ""}` : (p.name || ""));
      zeilen.push(p.strasse || "");
      zeilen.push(`${p.plz || ""} ${p.ort || ""}`.trim());
    });
    return zeilen.join("\n");
  }
  const vorsatz = typ === "eheleute" ? "Eheleute" : typ === "herr" ? "Herr"
    : typ === "frau" ? "Frau" : "";
  return [vorsatz, name || "", strasse || "", `${plz || ""} ${ort || ""}`.trim()]
    .filter((z) => z !== "").join("\n");
}

async function fillMietvertrag(e) {
  // Wie bei Maklervertrag und Objektnachweis: der Inhalt kommt aus den
  // markierten Stellen der eigenen Vorlage. Hier standen zuletzt die
  // Vornamen der Mietparteien, ihre Strasse, die Anschrift des Objekts, das
  // Kreditinstitut und die Hoehe der Miete aus einem Mustermietvertrag.
  const firma = STANDORTE[e.standort || "musterstadt"] || {};
  const { bytes, endung, warnungen } = await immoVorlageFuellen("mietvertrag", e, firma);
  const wer = (e.vermieter_typ === "erben" || e.vermieter_typ === "mehrere")
      && Array.isArray(e.vermieter_erben) && e.vermieter_erben[0] && e.vermieter_erben[0].name
    ? e.vermieter_erben[0].name
    : (e.vermieter_name || "Vermieter");
  const datei = `Mietvertrag_${fileSafe(wer)}_${fileSafe(e.objekt_strasse || "Objekt")}.${endung}`;
  immoDateiAnbieten(bytes, datei, endung);
  immoVorlageWarnungen(warnungen);
}


