function nhkInterpoliert(e, t) {
  const n = NHK_2010[e];
  if (!n) return 0;
  const a = parseFloat(String(t).replace(",", "."));
  if (isNaN(a)) return n.ss3 || 0;
  const r = [1, 2, 3, 4, 5].filter(e => null != n["ss" + e]);
  if (0 === r.length) return 0;
  const l = Math.min(...r),
    i = Math.max(...r),
    o = Math.max(l, Math.min(i, a)),
    s = Math.floor(o),
    c = Math.ceil(o);
  if (s === c) return n["ss" + s];
  let d = n["ss" + s],
    u = n["ss" + c];
  if (null == d) {
    const e = r.filter(e => e <= s).pop() || l;
    d = n["ss" + e]
  }
  if (null == u) {
    const e = r.find(e => e >= c) || i;
    u = n["ss" + e]
  }
  return d + (u - d) * (o - s)
}
