            React.createElement("td", { style: { padding: "7px 8px 7px 0", color: CI.blau } }, p.name,
              p.role === "chef" && React.createElement("span", { style: { marginLeft: 6, fontSize: 10.5, color: CI.gold, fontWeight: 600 } }, "Chef")),
            React.createElement("td", { style: { padding: "7px 0", textAlign: "right", width: 120 } },
              React.createElement("input", {
                type: "text", inputMode: "decimal", defaultValue: p.stundensatz == null ? "" : String(p.stundensatz),
                onBlur: (e) => stundensatzSetzen(p.id, e.target.value),
                style: { width: 90, padding: "5px 7px", border: `1px solid ${CI.border}`, fontFamily: FONT, fontSize: 12.5, color: CI.blau, textAlign: "right" }
              }), React.createElement("span", { style: { marginLeft: 6, color: CI.muted } }, "€/Std."))
