  doc.setFontSize(15); text(zpEuro(r.senkung) + "  (" + zpProzent(r.senkungProzent, 1) + ")", rand + 5, y + 10);
  doc.setFont("helvetica", "normal"); doc.setFontSize(10);
  text("auf " + zpEuro(r.kaufpreisNeu) + " — Rate " + zpEuro(r.rateAlt) + " statt " + zpEuro(r.rateNeu) + " im Monat", rand + 5, y + 16.5);
  y += 30;

  // Vergleichstabelle
