  const balken = [["Rate alt", r.rateAlt, navy], ["Rate neu", r.rateNeu, gold], ["Rate bei angepasstem Preis", r.rateAlt, [141, 155, 196]]];
  doc.setFont("helvetica", "bold"); doc.setFontSize(10); doc.setTextColor(navy[0], navy[1], navy[2]); text("Monatsrate im Vergleich", rand, y); y += 5;
