    doc.setFillColor(farbe[0], farbe[1], farbe[2]); doc.rect(rand + 48, y, w, 4.5, "F");
    doc.setTextColor(navy[0], navy[1], navy[2]); text(zpEuro(wert), rand + 50 + w, y + 3.5);
