/**
 * Posteingang immer in einem eigenen Browserfenster.
 * Das Fenster heisst "ep-posteingang"; gibt es das schon, wird es nur nach vorn
 * geholt (und bei Bedarf auf eine bestimmte Mail gelenkt) statt neu geladen.
 * In der iOS-App und im Posteingang-Fenster selbst bleibt alles wie gehabt.
 * Rueckgabe: true = extern geoeffnet, der Aufrufer navigiert dann nicht selbst.
 */
function epPosteingangExtern(mailId) {
  try {
    if (typeof pushInApp === "function" && pushInApp()) return false;
    if (window.name === "ep-posteingang") return false;
    const mailAn = window._epMailAn || null;
    const ziel = "#posteingang" + (mailId ? "/" + mailId : "");
    const url = window.location.pathname + window.location.search + ziel;
    // Leere URL: ein vorhandenes Fenster dieses Namens kommt zurueck, ohne neu zu laden
    const w = window.open("", "ep-posteingang");
    if (!w) return false;                                  // Pop-up-Blocker: dann im selben Fenster
    let leer = true;
    try { leer = !w.location || w.location.href === "about:blank" || !w.document || !w.document.body || !w.document.body.childElementCount; } catch (e) { leer = false; }
    if (mailAn) { window._epMailAn = null; epMailAnUebergeben(w, mailAn, leer); }
    if (leer) {
      w.location.href = url;
    } else if (mailId) {
      if (typeof w.epPushNavigiere === "function") w.epPushNavigiere(ziel);
      else w.location.href = url;
    } else if (typeof w.epPushNavigiere === "function" && !/^#posteingang/.test(w.location.hash || "")) {
      w.epPushNavigiere(ziel);
    }
    try { w.focus(); } catch (e) { /* egal */ }
    return true;
  } catch (e) {
    console.warn("Posteingang-Fenster:", e && e.message ? e.message : e);
    return false;
  }
}
window.epPosteingangExtern = epPosteingangExtern;
/**
 * Termine im Wochen- und Tagesraster ziehen.
 *
 * Maus/Stift: Ziehen beginnt nach 6 px Bewegung. Finger: langes Halten (400 ms),
 * damit das normale Blättern nicht gestört wird. Beim Ziehen rastet die Zeit in
 * 15-Minuten-Schritten ein, die Dauer bleibt erhalten; in der Wochenansicht kann
 * der Termin auch auf einen anderen Tag gezogen werden. Ein kleines Schild zeigt
 * die neue Zeit. Loslassen speichert wie „Bearbeiten → Speichern": Termin in der
 * Datenbank, Protokoll, Fahrzeiten beider Tage, Übertragung nach onOffice.
 * Escape bricht ab. Ein Klick ohne Bewegung öffnet den Termin wie bisher.
 *
 * Nicht ziehbar: ganztägige und mehrtägige Termine, stornierte Termine und Termine,
 * die im Portal ohnehin nur angesehen werden dürfen (z. B. Outlook-Einträge).
 */

const KAL_ZIEH_RASTER = 15;

let kalZiehZustand = null;
let kalZiehKlickSperre = 0;

function kalZiehErlaubt(t) {
  if (!t || !t.id || !t.uhrzeit || t.ganztags) return false;
  if (t.datum_ende && t.datum_ende !== t.datum) return false;
  if (t.status === "storniert") return false;
  const extern = String(t.onoffice_id || "").includes("@");
  return t.quelle === "portal" || (t.quelle === "onoffice" && !t.privat && !extern);
}

/** Nach einem Ziehen den nachfolgenden Klick verschlucken, sonst ginge der Termin auf. */
function kalZiehKlickAbfangen() {
  if (kalZiehKlickSperre && Date.now() - kalZiehKlickSperre < 600) { kalZiehKlickSperre = 0; return true; }
  return false;
}

function kalZiehMinutenText(min) {
  const h = Math.floor(min / 60), m = min % 60;
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

function kalZiehTagText(datum) {
  const d = kalS2D(datum);
  return `${KAL_WTAGE[(d.getDay() + 6) % 7]} ${String(d.getDate()).padStart(2, "0")}.${String(d.getMonth() + 1).padStart(2, "0")}.`;
}

function kalZiehAufraeumen() {
  const z = kalZiehZustand;
  if (!z) return;
  kalZiehZustand = null;
  try { z.box.releasePointerCapture(z.pointerId); } catch (e) { /* egal */ }
  clearTimeout(z.uhr);
  z.box.removeEventListener("pointermove", z.beiBewegung);
  z.box.removeEventListener("pointerup", z.beiEnde);
  z.box.removeEventListener("pointercancel", z.beiAbbruch);
  document.removeEventListener("keydown", z.beiTaste, true);
  document.removeEventListener("touchmove", z.beiTouch, { passive: false });
  if (z.schild && z.schild.parentNode) z.schild.parentNode.removeChild(z.schild);
  if (z.aktiv) {
    z.box.style.transform = "";
    z.box.style.zIndex = "";
    z.box.style.opacity = "";
    z.box.style.boxShadow = "";
    z.box.style.cursor = "";
    document.body.style.userSelect = "";
    document.body.style.webkitUserSelect = "";
  }
}

/**
 * ev: pointerdown auf dem Terminkasten; t: Termin; o: { q: px je Stunde, start: erste
 * Rasterstunde, verschieben(t, {datum, uhrzeit, ende}) -> Promise<boolean> }.
 */
function kalZiehStart(ev, t, o) {
  if (!kalZiehErlaubt(t)) return;
  if (ev.button != null && ev.button !== 0) return;
  if (kalZiehZustand) kalZiehAufraeumen();
  const box = ev.currentTarget;
  const spalte = box.closest("[data-kaltag]");
  if (!spalte || !spalte.parentElement) return;
  const spalten = Array.from(spalte.parentElement.querySelectorAll("[data-kaltag]"));
  const startMin = kalMin(t.uhrzeit) ?? 0;
  const endeMin = kalMin(t.ende);
  const dauer = Math.max(15, (endeMin != null && endeMin > startMin ? endeMin : startMin + 60) - startMin);
  const rect = box.getBoundingClientRect();

  const z = {
    box, spalte, spalten, t, o, dauer, startMin,
    pointerId: ev.pointerId, aktiv: false,
    x0: ev.clientX, y0: ev.clientY,
    griffY: ev.clientY - rect.top,          // wo im Kasten angefasst wurde
    neu: null, schild: null, uhr: null,
    touch: ev.pointerType === "touch"
  };
  kalZiehZustand = z;

  const beginnen = () => {
    if (!kalZiehZustand || z.aktiv) return;
    z.aktiv = true;
    try { box.setPointerCapture(z.pointerId); } catch (e) { /* egal */ }
    box.style.zIndex = "50";
    box.style.opacity = "0.88";
    box.style.boxShadow = "0 10px 24px rgba(16,32,64,0.28)";
    box.style.cursor = "grabbing";
    document.body.style.userSelect = "none";
    document.body.style.webkitUserSelect = "none";
    z.schild = document.createElement("div");
    z.schild.style.cssText = "position:fixed;z-index:9999;background:" + CI.blau + ";color:#fff;font:600 12px " + FONT +
      ";padding:4px 8px;border-radius:3px;pointer-events:none;box-shadow:0 2px 8px rgba(0,0,0,0.25);white-space:nowrap";
    document.body.appendChild(z.schild);
    z.beiTouch = (e) => { e.preventDefault(); };
    document.addEventListener("touchmove", z.beiTouch, { passive: false });
    zeichnen(z.x0, z.y0);
  };

  const zeichnen = (x, y) => {
    // Zieltag: Spalte unter dem Zeiger (nur waagerecht entschieden, damit man nicht "rausfällt")
    let ziel = spalte;
    for (const s of spalten) {
      const r = s.getBoundingClientRect();
      if (x >= r.left && x < r.right) { ziel = s; break; }
    }
    const zr = ziel.getBoundingClientRect();
    const hoehe = zr.height, q = o.q, start = o.start;
    const minutenImRaster = hoehe / q * 60;
    let neuStart = start * 60 + ((y - z.griffY) - zr.top) / q * 60;
    neuStart = Math.round(neuStart / KAL_ZIEH_RASTER) * KAL_ZIEH_RASTER;
    neuStart = Math.max(start * 60, Math.min(start * 60 + minutenImRaster - z.dauer, neuStart));
    neuStart = Math.max(0, Math.min(1440 - z.dauer, neuStart));
    const datum = ziel.getAttribute("data-kaltag");
    z.neu = { datum, startMin: neuStart };
    const dx = zr.left - spalte.getBoundingClientRect().left;
    const dy = (neuStart - z.startMin) / 60 * q;
    box.style.transform = `translate(${dx}px, ${dy}px)`;
    if (z.schild) {
      z.schild.textContent = `${kalZiehTagText(datum)} · ${kalZiehMinutenText(neuStart)}–${kalZiehMinutenText(neuStart + z.dauer)}`;
      z.schild.style.left = Math.round(x + 14) + "px";
      z.schild.style.top = Math.round(y - 34) + "px";
    }
  };

  z.beiBewegung = (e) => {
    if (kalZiehZustand !== z) return;
    if (!z.aktiv) {
      const weit = Math.abs(e.clientX - z.x0) > (z.touch ? 8 : 6) || Math.abs(e.clientY - z.y0) > (z.touch ? 8 : 6);
      if (!weit) return;
      if (z.touch) { kalZiehAufraeumen(); return; }     // Finger bewegt sich vor dem Halten: das ist Blättern
      beginnen();
    }
    zeichnen(e.clientX, e.clientY);
  };

  z.beiEnde = async () => {
    if (kalZiehZustand !== z) return;
    if (!z.aktiv) { kalZiehAufraeumen(); return; }
    const neu = z.neu;
    const alt = { datum: t.datum, startMin: z.startMin };
    kalZiehKlickSperre = Date.now();
    kalZiehAufraeumen();
    if (!neu || (neu.datum === alt.datum && neu.startMin === alt.startMin)) return;
    const werte = {
      datum: neu.datum,
      uhrzeit: kalZiehMinutenText(neu.startMin),
      ende: kalMin(t.ende) != null ? kalZiehMinutenText(neu.startMin + z.dauer) : null
    };
    try {
      await o.verschieben(t, werte);
    } catch (e) {
      alert("Der Termin konnte nicht verschoben werden: " + (e && e.message ? e.message : e));
    }
  };
  z.beiAbbruch = () => { if (kalZiehZustand === z) kalZiehAufraeumen(); };
  z.beiTaste = (e) => { if (e.key === "Escape" && kalZiehZustand === z) { e.stopPropagation(); kalZiehAufraeumen(); } };

  box.addEventListener("pointermove", z.beiBewegung);
  box.addEventListener("pointerup", z.beiEnde);
  box.addEventListener("pointercancel", z.beiAbbruch);
  document.addEventListener("keydown", z.beiTaste, true);
  if (z.touch) z.uhr = setTimeout(beginnen, 400);
}

/**
 * Speichert die neue Lage. Läuft wie das Speichern im Bearbeiten-Dialog, nur ohne
 * die dortigen Nachfragen zu Serie und Änderungs-Mail — dafür je eine kurze Rückfrage.
 */
async function kalTerminVerschieben(t, werte, user, einst, neuLaden) {
  const altText = `${kalZiehTagText(t.datum)} ${kalZeit(t.uhrzeit)}`;
  const neuText = `${kalZiehTagText(werte.datum)} ${werte.uhrzeit}`;
  if (t.serie_id && !confirm(`Dieser Termin gehört zu einer Serie.\n\nNur diesen einen Termin auf ${neuText} verschieben? Die übrigen Termine der Serie bleiben, wie sie sind.`)) return false;
  const kontakt = t.kontakte || t._kontakt || null;
  if (t.bestaetigung_gesendet_am && kontakt && kontakt.email &&
      !confirm(`Der Termin wurde dem Kunden (${kontakt.email}) bereits bestätigt.\n\nTrotzdem auf ${neuText} verschieben? Eine Änderungs-Mail kannst du danach über den Termin senden (öffnen → „Bestätigung senden“).`)) return false;

  await termineRepo.update(t.id, werte);
  try { await logAction("update", "termin", t.id, `${t.titel} verschoben: ${altText} → ${neuText}`); } catch (e) { /* egal */ }

  const fahrzeit = einst && einst.fahrzeit_aktiv !== false && (t.immobilie_id || String(t.ort || "").trim());
  if (fahrzeit && typeof kalFahrzeitTagAktualisieren === "function") {
    for (const tag of Array.from(new Set([t.datum, werte.datum]))) {
      try { await kalFahrzeitTagAktualisieren(tag, user, t.id); } catch (e) { /* Fahrzeit ist Beiwerk */ }
    }
  }

  try {
    const { data, error } = await window._sb.functions.invoke("onoffice-termin-schreiben", { body: { termin_id: t.id } });
    if (error || !data || !data.ok) throw new Error((data && data.fehler) || (error && error.message) || "Übertragung fehlgeschlagen");
  } catch (e) {
    alert(t.quelle === "onoffice"
      ? "Der Termin ist verschoben." + (e.message || e) + ""
      : "Der Termin ist verschoben." + (e.message || e));
  }
  if (typeof neuLaden === "function") await neuLaden();
  return true;
}
/**
 * Grundstücksdaten im Objekt (Reiter „Flächen & Eckdaten“).
 *
 * Werte liegen in immobilie_grundstueck (eine Zeile je Objekt), Schlüssel wie in
 * onOffice: erschliessung (erschlossen | teilerschlossen | unerschlossen),
 * bebaubar_nach (b_plan, bebauungsplan, nachbarbebauung, …), bebaubar_mit (Liste).
 * Bei onOffice-Objekten führt onOffice; der Import überschreibt nur Felder, die in
 * onOffice gefüllt sind — Portal-Einträge bleiben stehen, solange onOffice leer ist.
 */

const GS_ERSCHLIESSUNG = [["erschlossen", "Erschlossen"], ["teilerschlossen", "Teilerschlossen"], ["unerschlossen", "Unerschlossen"]];
const GS_BEBAUBAR_NACH = [
  ["b_plan", "B-Plan"], ["bebauungsplan", "Bebauungsplan (§30 BauGB)"], ["nachbarbebauung", "Nachbarbebauung (§34 BauGB)"],
  ["aussengebiet", "Außengebiet (§35 BauGB)"], ["bauland_ohne_b_plan", "Bauland ohne B-Plan"], ["bauerwartungsland", "Bauerwartungsland"],
  ["kein_bauland", "kein Bauland"], ["laenderspezifisch", "länderspezifisch"]
];
const GS_BEBAUBAR_MIT = [
  ["einfamilienhaus", "Einfamilienhaus"], ["doppelhaus", "Doppelhaus"], ["reihenhaus", "Reihenhaus"], ["mehrfamilienhaus", "Mehrfamilienhaus"],
  ["villa", "Villa"], ["gewerbe", "Gewerbe"], ["kleingewerbe", "Kleingewerbe"], ["buero", "Büro"], ["hotel", "Hotel"], ["gastronomie", "Gastronomie"],
  ["lager", "Lager"], ["produktion", "Produktion"], ["industrie", "Industrie"], ["garagen", "Garagen"], ["stellplaetze", "Stellplätze"], ["parkhaus", "Parkhaus"],
  ["einzelhandelgross", "Einzelhandel (groß)"], ["einzelhandelklein", "Einzelhandel (klein)"], ["garten", "Garten"], ["wald", "Wald"], ["ackerland", "Ackerland"],
  ["obstpflanzung", "Obstpflanzung"], ["camping", "Camping"], ["bootsstaende", "Bootsstände"], ["bauerwartungsland", "Bauerwartungsland"], ["keinebebauung", "keine Bebauung"]
];
const GS_FELDER = ["grz", "gfz", "erschliessung", "erschliessungskosten", "bebaubar_nach", "bebaubar_mit", "teilbar_ab"];

function gsText(liste, key) {
  const t = liste.find((p) => p[0] === String(key || ""));
  return t ? t[1] : String(key || "");
}

/** Hat die Zeile irgendeinen Inhalt (ohne Verwaltungsfelder)? */
function gsHatDaten(gs) {
  return !!gs && GS_FELDER.some((k) => Array.isArray(gs[k]) ? gs[k].length > 0 : gs[k] != null && gs[k] !== "");
}

/** Zeile fuer den Upsert: leere Eingaben werden null, Zahlen geparst. */
function gsZeile(immobilieId, gs) {
  const z = (v) => { if (v == null || String(v).trim() === "") return null; const n = Number(String(v).replace(",", ".")); return isFinite(n) ? n : null; };
  const t = (v) => { const s = v == null ? "" : String(v).trim(); return s || null; };
  return {
    immobilie_id: immobilieId,
    grz: t(gs.grz), gfz: t(gs.gfz),
    erschliessung: t(gs.erschliessung),
    erschliessungskosten: z(gs.erschliessungskosten),
    bebaubar_nach: t(gs.bebaubar_nach),
    bebaubar_mit: Array.isArray(gs.bebaubar_mit) && gs.bebaubar_mit.length ? gs.bebaubar_mit : null,
    teilbar_ab: z(gs.teilbar_ab),
    quelle: gs.quelle === "onoffice" ? "onoffice" : "portal",
    updated_at: new Date().toISOString()
  };
}

/** Speichert die Grundstuecksdaten; loescht die Zeile, wenn alles leer ist. */
async function gsSpeichern(immobilieId, gs) {
  if (!immobilieId || !gs) return;
  if (!gsHatDaten(gs)) {
    const { error } = await window._sb.from("immobilie_grundstueck").delete().eq("immobilie_id", immobilieId);
    if (error) throw error;
    return;
  }
  const { error } = await window._sb.from("immobilie_grundstueck").upsert(gsZeile(immobilieId, gs), { onConflict: "immobilie_id" });
  if (error) throw error;
}

function GrundstueckBlock({ daten, onAendern, quelle }) {
  const gs = daten || {};
  const feld = (label, inhalt) => React.createElement(ImmoFeld, { label: label }, inhalt);
  const eingabe = (k, extra) => React.createElement("input", {
    type: "text", style: inputStyle, value: gs[k] == null ? "" : gs[k],
    onChange: (e) => onAendern(k, e.target.value), ...(extra || {})
  });
  const auswahl = (k, liste, leer) => React.createElement("select", {
    style: inputStyle, value: gs[k] || "", onChange: (e) => onAendern(k, e.target.value)
  }, React.createElement("option", { value: "" }, leer || "–"),
    liste.map((p) => React.createElement("option", { key: p[0], value: p[0] }, p[1])));
  const mit = Array.isArray(gs.bebaubar_mit) ? gs.bebaubar_mit : [];
  const mitUmschalten = (key) => onAendern("bebaubar_mit", mit.includes(key) ? mit.filter((x) => x !== key) : [...mit, key]);

  return React.createElement("div", { style: { marginBottom: 18 } },
    React.createElement("div", { style: { fontSize: 14, fontWeight: 600, color: CI.blau, marginBottom: 4, marginTop: 6 } }, "Grundstück"),
    quelle === "onoffice"
      ? React.createElement("div", { style: { fontSize: 11, color: CI.muted, marginBottom: 10 } },
          "Wird bei einem Abgleich aus dem führenden System übernommen. Hier eingetragene Werte gelten, solange dort nichts steht.")
      : null,
    React.createElement("div", { className: "mob-keep", style: { display: "grid", gridTemplateColumns: "1fr 1fr 1fr 1fr 1fr", gap: 10, marginBottom: 10 } },
      feld("GRZ", eingabe("grz", { placeholder: "z. B. 0,4", inputMode: "decimal" })),
      feld("GFZ", eingabe("gfz", { placeholder: "z. B. 0,8", inputMode: "decimal" })),
      feld("Erschließung", auswahl("erschliessung", GS_ERSCHLIESSUNG, "– nicht angegeben –")),
      feld("Erschließungskosten €", eingabe("erschliessungskosten", { inputMode: "decimal" })),
      feld("Teilbar ab m²", eingabe("teilbar_ab", { inputMode: "decimal" }))
    ),
    React.createElement("div", { className: "mob-keep", style: { display: "grid", gridTemplateColumns: "1fr 2fr", gap: 10 } },
      feld("Bebaubar nach", auswahl("bebaubar_nach", GS_BEBAUBAR_NACH, "– nicht angegeben –")),
      React.createElement(ImmoFeld, { label: "Bebaubar mit" },
        React.createElement("div", { style: { display: "flex", flexWrap: "wrap", gap: 6, paddingTop: 4 } },
          GS_BEBAUBAR_MIT.map((p) => React.createElement("button", {
            key: p[0], type: "button", onClick: () => mitUmschalten(p[0]),
            style: {
              fontSize: 11, padding: "3px 8px", cursor: "pointer", fontFamily: FONT,
              border: `1px solid ${mit.includes(p[0]) ? CI.blau : CI.border}`,
              background: mit.includes(p[0]) ? CI.blau : "#fff", color: mit.includes(p[0]) ? "#fff" : CI.blau
            }
          }, p[1]))))));
}
/**
 * Dateien per Drag & Drop an eine Mail hängen.
 *
 * Solange der Mail-Editor offen ist (erkennbar am Datei-Eingabefeld mit
 * data-mail-anhang), nimmt die ganze Seite Dateien an: Beim Hereinziehen
 * erscheint eine Ablagefläche, beim Loslassen laufen die Dateien durch dieselbe
 * Prüfung wie „Datei anhängen“ (25 MB je Datei, 40 MB gesamt). Ablagen, die ein
 * anderer Bereich schon behandelt hat (z. B. der Datei-Upload am Objekt), werden
 * nicht angefasst.
 */
(function () {
  if (typeof document === "undefined") return;
  let tiefe = 0;
  let flaeche = null;

  const editorOffen = () => !!document.querySelector("input[data-mail-anhang]") && typeof window.__mailDateienAnhaengen === "function";
  const hatDateien = (e) => !!(e.dataTransfer && Array.from(e.dataTransfer.types || []).includes("Files"));

  const zeigen = () => {
    if (flaeche) return;
    flaeche = document.createElement("div");
    flaeche.id = "ep-mail-ablage";
    flaeche.style.cssText = "position:fixed;inset:0;z-index:9990;background:rgba(38,49,89,0.55);display:flex;align-items:center;justify-content:center;pointer-events:none";
    const kasten = document.createElement("div");
    kasten.style.cssText = "border:2px dashed #D4A567;background:#fff;color:#263159;padding:28px 40px;font:600 15px " + (typeof FONT === "string" ? FONT : "sans-serif") +
      ";text-align:center;box-shadow:0 12px 40px rgba(0,0,0,0.3)";
    kasten.innerHTML = "📎 Dateien hier loslassen<div style=\"font-size:12px;font-weight:400;color:#6b7280;margin-top:6px\">werden an die Mail angehängt (max. 25 MB je Datei, 40 MB gesamt)</div>";
    flaeche.appendChild(kasten);
    document.body.appendChild(flaeche);
  };
  const verstecken = () => { tiefe = 0; if (flaeche && flaeche.parentNode) flaeche.parentNode.removeChild(flaeche); flaeche = null; };

  document.addEventListener("dragenter", (e) => {
    if (!editorOffen() || !hatDateien(e)) return;
    tiefe++;
    zeigen();
  });
  document.addEventListener("dragover", (e) => {
    if (!editorOffen() || !hatDateien(e)) return;
    e.preventDefault();                       // sonst erlaubt der Browser kein Ablegen
    if (e.dataTransfer) e.dataTransfer.dropEffect = "copy";
  });
  document.addEventListener("dragleave", (e) => {
    if (!flaeche) return;
    tiefe = Math.max(0, tiefe - 1);
    if (tiefe === 0 || e.clientX <= 0 || e.clientY <= 0) verstecken();
  });
  document.addEventListener("drop", (e) => {
    const war = !!flaeche;
    verstecken();
    if (!editorOffen() || !hatDateien(e)) return;
    if (e.defaultPrevented) return;           // ein anderer Bereich hat die Ablage schon angenommen
    e.preventDefault();
    const dateien = Array.from(e.dataTransfer.files || []);
    if (!dateien.length || !war && !dateien.length) return;
    try { window.__mailDateienAnhaengen(dateien); }
    catch (err) { alert("Dateien konnten nicht angehängt werden: " + (err && err.message ? err.message : err)); }
  });
  // Ohne offenen Editor bleibt alles wie bisher: der Browser öffnet die Datei nicht,
  // weil wir Ablagen nur mit Editor annehmen — dieses Verhalten war schon vorher so.
})();

/**
 * Termin-Hinweis im Adressbuch: zeigt je Kontakt den nächsten anstehenden Termin,
 * sonst den letzten Termin der vergangenen 90 Tage. Grundlage ist termine.kontakt_id.
 */
async function kontaktTermineLaden() {
  const heute = new Date();
  const iso = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  const ab = new Date(heute); ab.setDate(ab.getDate() - 90);
  const { data, error } = await window._sb.from("termine")
    .select("id, titel, art, datum, uhrzeit, kontakt_id, status")
    .not("kontakt_id", "is", null)
    .neq("status", "storniert")
    .gte("datum", iso(ab))
    .order("datum", { ascending: true }).order("uhrzeit", { ascending: true, nullsFirst: true })
    .limit(3000);
  if (error) throw error;
  const heuteIso = iso(heute);
  const aus = {};
  for (const t of data || []) {
    const kommend = t.datum >= heuteIso;
    const alt = aus[t.kontakt_id];
    if (!alt) { aus[t.kontakt_id] = { ...t, kommend }; continue; }
    if (kommend && !alt.kommend) { aus[t.kontakt_id] = { ...t, kommend }; continue; }   // kommend schlägt vergangen
    if (kommend === alt.kommend && !kommend) aus[t.kontakt_id] = { ...t, kommend };       // bei Vergangenem: der jüngste
    // bei Kommendem bleibt der früheste (Liste ist aufsteigend sortiert)
  }
  return aus;
}

function kontaktTerminText(t) {
  const d = new Date(t.datum + "T12:00:00");
  const tag = ["So", "Mo", "Di", "Mi", "Do", "Fr", "Sa"][d.getDay()];
  const datum = `${tag} ${String(d.getDate()).padStart(2, "0")}.${String(d.getMonth() + 1).padStart(2, "0")}.`;
  const zeit = t.uhrzeit ? " " + String(t.uhrzeit).slice(0, 5) : "";
  const art = t.art && t.art !== "Sonstiges" ? t.art : (t.titel || "Termin");
  return `${datum}${zeit} · ${art}`;
}

function KontaktTerminHinweis({ termin }) {
  if (!termin) return null;
  return React.createElement("div", {
    title: termin.titel || "",
    style: { color: termin.kommend ? CI.gold : CI.muted, fontWeight: termin.kommend ? 600 : 400 }
  }, termin.kommend ? "📅 Termin " : "📅 letzter Termin ", kontaktTerminText(termin));
}
// ===================== Adressbuch: „Anlegen“ und „Weitere Aktionen“ am Kontakt =====================
