  if (!r.ok) throw new Error("Ortssuche antwortet nicht (HTTP " + r.status + ").");
  const liste = await r.json();
  if (!Array.isArray(liste) || !liste.length) throw new Error(`Ort „${label}“ nicht gefunden.`);
