  const dateiname = (kwName(k) || "Kontakt").replace(/[^\wäöüÄÖÜß .-]+/g, "_") + ".vcf";
  const vcf = kwVCard(k);
  const herunterladen = () => {
    if (window.EPApp && typeof window.EPApp.teilen === "function") { window.EPApp.teilen({ text: vcf, dateiname }); return; }
    const url = URL.createObjectURL(new Blob([vcf], { type: "text/vcard;charset=utf-8" }));
    const a = document.createElement("a"); a.href = url; a.download = dateiname; document.body.appendChild(a); a.click();
    setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 500);
  };
  const perMail = () => {
    window._epMailAn = { an: "", name: "", betreff: "Kontakt: " + kwName(k), text: kwKontaktText(k), anhaenge: [new File([vcf], dateiname, { type: "text/vcard" })] };
    if (window.setView) window.setView("posteingang");
    onClose();
  };
  const kopieren = async () => {
    try { await navigator.clipboard.writeText(kwKontaktText(k)); setHinweis("Kontaktdaten in die Zwischenablage kopiert."); }
    catch (e) { setHinweis("Kopieren nicht möglich — bitte den Text unten markieren."); }
  };
  return React.createElement(KwDialog, { titel: "Kontakt versenden", onClose },
    React.createElement("pre", { style: { fontFamily: FONT, fontSize: 12.5, color: CI.blau, background: "#f7f7f9", padding: 12, whiteSpace: "pre-wrap", margin: "0 0 12px" } }, kwKontaktText(k)),
    React.createElement("div", { style: { display: "flex", gap: 8, flexWrap: "wrap" } },
      React.createElement("button", { type: "button", onClick: herunterladen, style: primaryBtn }, window.EPApp ? "📤 Teilen (vCard)" : "⬇️ vCard herunterladen"),
      React.createElement("button", { type: "button", onClick: perMail, style: secondaryBtn }, "✉ Per E-Mail senden"),
      React.createElement("button", { type: "button", onClick: kopieren, style: secondaryBtn }, "📋 Text kopieren")),
    React.createElement("div", { style: { fontSize: 11.5, color: CI.muted, marginTop: 10 } }, "Die vCard lässt sich auf jedem Telefon direkt ins Adressbuch übernehmen. „Per E-Mail senden“ öffnet eine neue Mail mit den Kontaktdaten im Text und der vCard als Anhang."),
    React.createElement(KwFuss, { hinweis, onAbbrechen: onClose }));
