// ===================== Suchkriterien: Abgleich Objekt <-> Interessent, Nachfrage =====================
// Datenbank: kontakte.such_profil (Kriterien), suchkriterien_treffer (Abgleich per SQL),
// RPC suchkriterien_abgleich(p_immobilie, p_kontakt), RPC suchkriterien_nachfrage(...).
// Hier: Karte am Objekt („Passende Interessenten“ mit Exposé-Link-Versand), Karte am
// Kontakt („Passende Objekte“), Knopf in der Anfrage („Suchkriterium anlegen“),
// Nachfrage-Zeile (Einwertung) und Admin-Auswertung „Nachfrage“.

function skPreis(o) {
  const miete = /^(verm|miet)/i.test(String(o.vertragsart || ""));
  const p = miete ? o.kaltmiete : o.angebotspreis;
  return p ? { wert: Number(p), miete } : { wert: null, miete };
}
function skPreisText(o) { const p = skPreis(o); return p.wert ? Number(p.wert).toLocaleString("de-DE") + " €" + (p.miete ? " kalt" : "") : ""; }
function skObjektTitel(o) { return o.objekttitel || o.bezeichnung || ("Objekt " + (o.immo_nr || "")); }
function skObjektZeile(o) { return [o.immo_nr ? "Nr. " + o.immo_nr : "", [o.plz, o.ort].filter(Boolean).join(" "), o.objektart, skPreisText(o), o.zimmer ? o.zimmer + " Zi." : "", o.wohnflaeche ? Math.round(o.wohnflaeche) + " m²" : ""].filter(Boolean).join(" · "); }
const SK_STATUS_LABEL = { aktiv: "aktiv", pausiert: "pausiert", erfuellt: "erfüllt" };
const SK_OBJEKT_STATUS = { akquise: "Akquise", vermarktung: "Vermarktung", reserviert: "Reserviert", verkauft: "Verkauft", archiviert: "Archiviert" };

async function skAbgleich(p) {
  const { data, error } = await window._sb.rpc("suchkriterien_abgleich", { p_immobilie: p.immobilie_id || null, p_kontakt: p.kontakt_id || null });
  if (error) throw error;
  return Array.isArray(data) ? data[0] : data;
}
/** Vorschlag fuer ein Suchkriterium aus einem Objekt (Anfrage): Art, Ort, PLZ-Bereich, Preis +15 %. */
function skVorbelegungAusObjekt(o) {
  if (!o) return {};
  const p = skPreis(o);
  const art = /^Sonstige/i.test(o.objektart || "") ? "Sonstiges" : (o.objektart || "");
  const rund = p.miete ? 10 : 1000;
  return {
    vermarktungsart: [p.miete ? "miete" : "kauf"], objektarten: art ? [art] : [],
    orte: o.ort || "", plz: o.plz ? String(o.plz).slice(0, 3) : "",
    preis_bis: p.wert ? Math.round(p.wert * 1.15 / rund) * rund : "",
    zimmer_von: o.zimmer ? Math.max(1, Math.floor(Number(o.zimmer)) - 1) : "",
    flaeche_von: o.wohnflaeche ? Math.round(Number(o.wohnflaeche) * 0.8 / 5) * 5 : ""
  };
}
function skPunkteBadge(p) {
  const farbe = p >= 70 ? CI.success : p >= 40 ? CI.gold : CI.muted;
  return React.createElement("span", { title: "Übereinstimmung mit dem Suchkriterium", style: { fontSize: 11, fontWeight: 700, color: "#fff", background: farbe, padding: "2px 7px", borderRadius: 10, flexShrink: 0 } }, p + " %");
}
function skChips(gruende) {
  return React.createElement("span", { style: { display: "inline-flex", gap: 4, flexWrap: "wrap" } },
    (gruende || []).map((g, i) => React.createElement("span", { key: i, style: { fontSize: 10.5, color: CI.blau, background: `${CI.gold}22`, padding: "1px 6px" } }, g)));
}
async function skPostfach(userId) {
  const { data } = await window._sb.from("mail_postfaecher").select("id, email_adresse").eq("benutzer_id", userId).eq("aktiv", true)
    .order("standard_zum_senden", { ascending: false }).order("ist_standard", { ascending: false }).limit(1);
  return data && data[0] || null;
}
function skNutzer() { return { id: window._currentUserId || null, name: window._currentUserName || "" }; }
function skKontaktOeffnen(id) { window._epKontaktOeffnen = id; if (window.setView) { window.setView("home"); setTimeout(() => window.setView("kontakte"), 30); } }
function skObjektOeffnen(id) {
  // Der Bestand liest window._epObjektOeffnen beim Laden seiner Liste (wie „Zuletzt geöffnet“).
  window._epObjektOeffnen = id;
  if (!window.setView) { window.location.hash = "#immobilien/" + id; return; }
  const aktuell = String((window.EPApp && window.EPApp.aktiveSeite) || (window.location.hash || "").replace(/^#/, "").split(/[\/?]/)[0]);
  if (aktuell === "immobilien") { window.setView("home"); setTimeout(() => window.setView("immobilien"), 40); } else window.setView("immobilien");
}

/** Exposé-Link erzeugen (wie im Posteingang) und per Mail an den Interessenten schicken. */
async function skExposeLinkSenden({ objekt, kontakt, nutzer, provisionFragen }) {
  if (!kontakt.email) throw new Error("Kontakt hat keine E-Mail-Adresse.");
  let body = { immobilie_id: objekt.id, email: kontakt.email, name: kwName(kontakt), kontakt_id: kontakt.id };
  let { data: t, error } = await window._sb.functions.invoke("expose-freigabe-erstellen", { body });
  if (error) throw error;
  if (t && !t.ok && /Käuferprovision/.test(t.fehler || "")) {
    const prov = provisionFragen();
    if (prov === null) throw new Error("abgebrochen");
    body = { ...body, provision: prov.trim() || null, provisionsmodell: prov.trim() ? "kaeufer" : "provisionsfrei" };
    ({ data: t, error } = await window._sb.functions.invoke("expose-freigabe-erstellen", { body }));
    if (error) throw error;
  }
  if (!t || !t.ok) throw new Error((t && t.fehler) || "Exposé-Link konnte nicht erzeugt werden.");
  const pf = await skPostfach(nutzer.id);
  if (!pf) throw new Error("Kein aktives Postfach zum Senden.");
  const nn = kontakt.nachname || "";
  const anrede = kontakt.anrede === "Herr" && nn ? `Sehr geehrter Herr ${nn}` : kontakt.anrede === "Frau" && nn ? `Sehr geehrte Frau ${nn}` : `Guten Tag ${kwName(kontakt)}`;
  const zeile = [skObjektTitel(objekt), [objekt.plz, objekt.ort].filter(Boolean).join(" "), skPreisText(objekt), objekt.zimmer ? objekt.zimmer + " Zimmer" : "", objekt.wohnflaeche ? Math.round(objekt.wohnflaeche) + " m² Wohnfläche" : ""].filter(Boolean).join(" · ");
  const av = await epExposeAnschreiben({ objekt, kontakt, nutzer, url: t.url, postfach: pf }).catch(() => null);
  const text = av ? av.text : `${anrede},\n\nzu Ihrer Suche passt eines unserer Objekte:\n\n${zeile}\n\nIhr persönlicher Exposé-Link:\n${t.url}\n(Nach Bestätigung der Pflichtangaben steht Ihnen das Exposé sofort zum Download bereit.)\n\nBei Fragen oder für eine Besichtigung melden Sie sich gern bei mir.\n\nMit freundlichen Grüßen\n${nutzer.name || ""}`;
  const { data: m, error: e2 } = await window._sb.functions.invoke("mail-senden", { body: { postfach_id: pf.id, an: kontakt.email, an_name: kwName(kontakt), betreff: (av && av.betreff) || `Exposé: ${skObjektTitel(objekt)}`, text } });
  if (e2) throw e2;
  if (!m || !m.ok) throw new Error((m && m.error) || "Mailversand fehlgeschlagen.");
  await window._sb.from("suchkriterien_treffer").update({ expose_gesendet_am: new Date().toISOString() }).eq("kontakt_id", kontakt.id).eq("immobilie_id", objekt.id);
  return t.url;
}

