// ---------- Posteingang: Suchkriterium aus der Anfrage ----------
function AnfrageSuchkriteriumKnopf({ mail }) {
  const [dialog, setDialog] = useState(null); const [busy, setBusy] = useState(false);
  if (!mail || !mail.anfrage_daten || mail.anfrage_daten.art === "eigentuemer") return null;
  const oeffnen = async () => {
    if (!mail.kontakt_id) { alert("Der Interessent ist noch nicht im Adressbuch. Bitte zuerst übernehmen, dann lässt sich das Suchkriterium anlegen."); return; }
    setBusy(true);
    try {
      const [{ data: k }, { data: o }] = await Promise.all([
        window._sb.from("kontakte").select("*").eq("id", mail.kontakt_id).maybeSingle(),
        mail.immobilie_id ? window._sb.from("immobilien").select("id, immo_nr, objektart, vertragsart, plz, ort, angebotspreis, kaltmiete, zimmer, wohnflaeche").eq("id", mail.immobilie_id).maybeSingle() : Promise.resolve({ data: null })
      ]);
      if (!k) throw new Error("Kontakt nicht gefunden.");
      // Hat der Kontakt schon ein Kriterium mit Inhalt, wird ein weiteres angelegt
      const alle = kwSuchprofile(k);
      setDialog({ kontakt: k, vorbelegung: skVorbelegungAusObjekt(o), index: alle.length && kwSuchprofilHatInhalt(alle[0]) ? alle.length : 0 });
    } catch (e) { alert("Suchkriterium: " + kwFehlertext(e)); }
    setBusy(false);
  };
  return React.createElement(React.Fragment, null,
    React.createElement("button", { type: "button", onClick: oeffnen, disabled: busy, title: "Suchkriterium für diesen Interessenten anlegen — vorbelegt aus dem angefragten Objekt",
      style: { marginLeft: 8, background: "#fff", border: `1px solid ${CI.gold}`, color: CI.blau, fontSize: 11, padding: "2px 8px", cursor: "pointer", fontFamily: FONT, fontWeight: 600 } }, "🔍 Suchkriterium"),
    dialog && React.createElement(KwSuchkriterium, { kontakt: dialog.kontakt, vorbelegung: dialog.vorbelegung, index: dialog.index, onClose: () => setDialog(null) }));
}

