const IMMO_OFF_OA_OBJEKTARTEN = ["Einfamilienhaus", "Doppelhaushälfte", "Reihenhaus", "Reihenendhaus", "Eigentumswohnung", "Mehrfamilienhaus", "Bungalow", "Villa", "Grundstück", "Gewerbe"];
