/** Telefonate, die aus der Lead-Seite heraus gewählt werden, landen automatisch als Aktivität am Lead. */
function AkqLeadKontext({ lead, user, onGeaendert }) {
  useEffect(() => {
    const h = async (ev) => {
      const v = ev && ev.detail && ev.detail.vermerk;
      if (!v) return;
      try {
        await window._sb.from("akq_aktivitaeten").insert({ lead_id: lead.id, typ: "anruf", betreff: "Telefonat · " + akqEigentuemerName(lead), notiz: "Aus der World gewählt" + (v.rufnummer ? " (" + v.rufnummer + ")" : ""), faellig_am: v.begonnen_am || new Date().toISOString(), erledigt_am: new Date().toISOString(), prioritaet: "normal", zustaendig_id: user.id, erstellt_von: user.id });
        await akqHistorieSchreiben(lead.id, user, [{ feld: "kontakt", alt: "", neu: "Telefonat gewählt" + (v.rufnummer ? " (" + v.rufnummer + ")" : "") }]);
        if (onGeaendert) onGeaendert();
      } catch (e) { console.warn("Telefonat am Lead:", e); }
    };
    window.addEventListener("ep-telefonat-angelegt", h);
    return () => window.removeEventListener("ep-telefonat-angelegt", h);
  }, [lead.id]);
  return null;
}

/** Legt aus dem Lead ein Objekt im Status Akquise an und verknüpft Lead, Kontakt und Eigentümer. */
async function akqObjektAusLead(lead, user) {
  const k = lead.kontakte || null;
  const zahl = (v) => (v == null || v === "" || isNaN(Number(v)) ? null : Number(v));
  const satz = {
    bezeichnung: akqLeadTitel(lead), objekttitel: lead.titel || null,
    strasse: lead.strasse || null, hausnummer: lead.hausnummer || null, plz: lead.plz || null, ort: lead.ort || null,
    objektart: lead.objektart || null, wohnflaeche: zahl(lead.wohnflaeche), grundstueck: zahl(lead.grundstueck), zimmer: zahl(lead.zimmer),
    baujahr: lead.baujahr ? parseInt(lead.baujahr, 10) : null, zustand: lead.zustand || null,
    vertragsart: "verkauf", status: "akquise", quelle: "akquise",
    angebotspreis: zahl(lead.startpreis) || zahl(lead.wert_schaetzung),
    lage_koordinaten: lead.lat && lead.lon ? { lat: Number(lead.lat), lon: Number(lead.lon) } : null,
    zustaendig_id: lead.zustaendig_id || user.id, ersteller_id: user.id,
  };
  const { data: immo, error } = await window._sb.from("immobilien").insert(satz).select("id, bezeichnung, immo_nr").single();
  if (error) throw error;
  const { error: le } = await window._sb.from("akq_leads").update({ immobilie_id: immo.id }).eq("id", lead.id);
  if (le) throw le;
  if (lead.kontakt_id) { try { await window._sb.from("kontakt_objekt").insert({ kontakt_id: lead.kontakt_id, immobilie_id: immo.id, rolle: "eigentuemer", ersteller_id: user.id }); } catch (e) { console.warn("Kontakt-Objekt:", e); } }
  if (k && k.eigentuemer_id) { try { await window._sb.from("immobilie_eigentuemer").insert({ immobilie_id: immo.id, eigentuemer_id: k.eigentuemer_id, rolle: "eigentuemer" }); } catch (e) { console.warn("Eigentümer-Objekt:", e); } }
  await akqHistorieSchreiben(lead.id, user, [{ feld: "objekt_angelegt", alt: "", neu: immo.bezeichnung || immo.id }]);
  return immo;
}

function AkqObjektAnlegenKnopf({ lead, user, onGeaendert }) {
  const [busy, setBusy] = useState(false);
  if (lead.immobilie_id) return null;
  return React.createElement("span", { "data-akq-objekt-anlegen": "1", style: { display: "inline-flex" } }, React.createElement(AkqBtn, { klein: true, variante: "grau", disabled: busy, onClick: async () => {
    const frage = typeof window.epBestaetigungsDialog === "function"
      ? await window.epBestaetigungsDialog({ titel: "Objekt aus dem Lead anlegen?", text: `„${akqLeadTitel(lead)}“ wird als Objekt im Status Akquise angelegt. Adresse, Objektdaten, Preis und Eigentümer werden übernommen, der Lead bleibt bestehen und wird verknüpft.`, knopf: "Objekt anlegen" })
      : (confirm("Objekt aus dem Lead anlegen?") ? "ja" : "nein");
    if (frage !== "ja") return;
    setBusy(true);
    try {
      const immo = await akqObjektAusLead(lead, user);
      if (typeof window.epHinweis === "function") window.epHinweis("Objekt „" + (immo.bezeichnung || "") + "“ angelegt (Status Akquise).");
      if (onGeaendert) await onGeaendert();
    } catch (e) { alert("Objekt konnte nicht angelegt werden: " + (e && e.message || e)); }
    setBusy(false);
  } }, busy ? "Legt an…" : "Objekt anlegen"));
}

/** Tage seit der letzten Aktivität (erledigt oder angelegt), Untergrenze: Anlage des Leads. */
function akqTageOhneAktivitaet(lead, aktivitaeten) {
  let letzte = new Date(lead.created_at || 0).getTime();
  (aktivitaeten || []).forEach((a) => { if (a.lead_id !== lead.id) return; for (const f of [a.erledigt_am, a.created_at]) { const t = f ? new Date(f).getTime() : 0; if (t > letzte && t <= Date.now()) letzte = t; } });
  return Math.floor((Date.now() - letzte) / 864e5);
}
function AkqInaktivHinweis({ lead, aktivitaeten }) {
  if (lead.status !== "offen") return null;
  const tage = akqTageOhneAktivitaet(lead, aktivitaeten);
  if (tage < 3) return null;
  return React.createElement("div", { "data-akq-inaktiv": tage, style: { fontSize: 10.5, color: tage >= 7 ? CI.danger : CI.muted, marginBottom: 6, fontWeight: tage >= 7 ? 700 : 400 } }, "⏱ " + tage + " Tage ohne Aktivität");
}

/** CSV mit Semikolon und BOM (Excel), Download über Blob. */
function akqLeadsCsv(leads, stamm) {
  const name = (liste, id) => { const x = (liste || []).find((e) => e.id === id); return x ? x.name : ""; };
  const kopf = ["Angelegt", "Straße", "PLZ", "Ort", "Eigentümer", "E-Mail", "Telefon", "Objektart", "Wohnfläche", "Grundstück", "Zimmer", "Baujahr", "Wertschätzung", "Startpreis", "Erwartete Provision", "Pipeline", "Stufe", "Status", "Verlustgrund", "Quelle", "Zuständig", "Tags", "Nächster Schritt", "Verkaufszeitraum", "Notiz"];
  const zelle = (v) => { const s = v == null ? "" : String(v).replace(/\r?\n/g, " "); return /[;"\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
  const zeilen = leads.map((l) => { const k = l.kontakte || {}, a = l.immobilien || l; return [
    l.created_at ? String(l.created_at).slice(0, 10) : "", [a.strasse, a.hausnummer].filter(Boolean).join(" ") || l.titel || "", a.plz || "", a.ort || "", akqEigentuemerName(l) === "—" ? "" : akqEigentuemerName(l), k.email || "", k.telefon || k.mobil || "",
    a.objektart || "", a.wohnflaeche || "", a.grundstueck || "", a.zimmer || "", a.baujahr || "", l.wert_schaetzung || "", l.startpreis || "", l.provision_erwartet || "",
    name(stamm.pipelines, l.pipeline_id), name(stamm.stufen, l.stufe_id), l.status || "", l.verlustgrund || "", name(stamm.quellen, l.quelle_id), name(stamm.profile, l.zustaendig_id), (l.tags || []).join(", "), l.naechster_schritt_am || "", l.verkaufszeitraum || "", l.notiz || ""].map(zelle).join(";"); });
  return "﻿" + kopf.join(";") + "\r\n" + zeilen.join("\r\n") + "\r\n";
}
function akqCsvHerunterladen(text, dateiname) {
  const blob = new Blob([text], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = dateiname; document.body.appendChild(a); a.click();
  setTimeout(() => { URL.revokeObjectURL(url); a.remove(); }, 1500);
}

