    const { data } = await window._sb.from("kontakt_objekt").select("kontakt_id, kontakte(id, anrede, titel, vorname, nachname, firma, email, rollen, eigentuemer_id)").eq("immobilie_id", immobilieId).eq("rolle", "eigentuemer").limit(1);
