  const personen = epPersonListe(k), namen = personen.map(epPersonName).filter(Boolean);
  if (namen.length < 2) return namen[0] || "";
  const nach = personen.map((p) => String(p.nachname || "").trim());
  if (nach.every((n) => n && n === nach[0])) {
    const vorn = personen.map((p) => [p.titel, p.vorname].map((x) => String(x || "").trim()).filter(Boolean).join(" "));
    if (vorn.every(Boolean)) return vorn.join(" & ") + " " + nach[0];
  }
