// ---- Stufe 70: Einstellungen im Portal (22.09.2026) ----
// Firmendaten, Signatur und Vorgabewerte standen an drei Stellen: in der Tabelle firma_stammdaten,
// fest im Programm (STANDORTE, IMMO_SIGNATUR) und als Zahlen mitten im Quelltext. Ab hier gilt die
// Datenbank; das fest Eingebaute bleibt nur als Notnagel, damit Verträge auch dann noch entstehen,
// wenn die Tabelle einmal nicht erreichbar ist.
window.__epEinst = window.__epEinst || null;
window.__epFirmen = window.__epFirmen || null;

// Was fuer einen neuen Vertrag/Nachweis/Reservierung gilt. Gerechnet hat
// es die Datenbank (vorlage_vorgaben); hier steht nur der Zugriff und
// der Notnagel, falls der Aufruf beim Start ausgefallen ist.
window.__immoVorgaben = window.__immoVorgaben || null;
function immoVorgabe(art, feld, ersatz) {
  const alle = window.__immoVorgaben;
  const wert = alle && alle[art] ? alle[art][feld] : undefined;
  if (wert === null || wert === undefined || wert === "") return ersatz;
  return String(wert);
}
function epEinst(schluessel, vorgabe) {
  const alle = window.__epEinst;
  if (!alle || !(schluessel in alle)) return vorgabe;
  const wert = alle[schluessel];
  if (wert === null || wert === undefined || wert === "") return vorgabe;
  return typeof wert === "string" ? wert : String(wert);
}
async function epEinstSetzen(schluessel, wert) {
  const { error } = await window._sb.from("portal_einstellungen").upsert(
    { mandant_id: window.IMMO_MANDANT_ID || null, schluessel, wert,
      updated_at: new Date().toISOString(), updated_by: window._currentUserId || null },
    { onConflict: "mandant_id,schluessel" });
  if (error) throw error;
  window.__epEinst = { ...(window.__epEinst || {}), [schluessel]: wert };
}
// Die Vertrags-PDFs greifen an acht Stellen auf STANDORTE zu. Statt jede einzeln umzubauen,
// werden die Einträge hier aus der Tabelle überschrieben - ein Weg, ein Risiko.
function epStandorteUebernehmen() {
  (window.__epFirmen || []).forEach((f) => {
    if (!f || f.typ !== "standort" || f.aktiv === false) return;
    const slug = String(f.slug || "").trim();
    if (!slug) return;
    const alt = STANDORTE[slug] || {};
    STANDORTE[slug] = {
      name: f.marken_name || alt.name || f.firma_name || "",
      firma: f.firma_name || alt.firma || "",
      strasse: f.strasse || alt.strasse || "",
      plz_ort: [f.plz, f.ort].filter(Boolean).join(" ") || alt.plz_ort || "",
      stadt: f.ort || alt.stadt || "",
    };
  });
}
async function epStammLaden(erneut) {
  if (window.__epStammLauf && !erneut) return window.__epStammLauf;
  window.__epStammLauf = (async () => {
    // Ein leeres oder fehlgeschlagenes Laden darf den Zwischenspeicher NICHT leeren: sonst faellt
    // die Oberflaeche auf die Vorgabewerte zurueck und schreibt sie beim naechsten Speichern ueber
    // die echten Einstellungen. Lieber der alte Stand als ein stillschweigend falscher.
    try {
      const { data, error } = await window._sb.from("portal_einstellungen").select("schluessel, wert");
      if (error) throw error;
      if (Array.isArray(data) && data.length) {
        const m = {};
        data.forEach((z) => { if (z && z.schluessel) m[z.schluessel] = z.wert; });
        window.__epEinst = m;
      }
    } catch (e) { console.warn("Einstellungen laden:", (e && e.message) || e); }
    try {
      const arten = ["maklervertrag", "objektnachweis", "reservierung"];
      const ergebnis = {};
      for (const art of arten) {
        const { data } = await window._sb.rpc("vorlage_vorgaben", {
          p_art: art, p_gesellschaft: window.IMMO_GESELLSCHAFT_ID || null });
        if (data) ergebnis[art] = data;
      }
      window.__immoVorgaben = ergebnis;
    } catch (e) { console.warn("Vorgaben der Vorlagen laden:", (e && e.message) || e); }
    try {
      const { data, error } = await window._sb.from("firma_stammdaten").select("*").order("sortierung");
      if (error) throw error;
      if (Array.isArray(data) && data.length) { window.__epFirmen = data; epStandorteUebernehmen(); }
    } catch (e) { console.warn("Firmenstamm laden:", (e && e.message) || e); }
    return true;
  })();
  return window.__epStammLauf;
}
function epFirma(slug) {
  const liste = window.__epFirmen || [];
  const s = String(slug || "").trim();
  return liste.find((f) => f && f.slug === s)
    || liste.find((f) => f && f.typ === "standort" && f.aktiv !== false) || null;
}
const IMMO_SIGNATUR_PLATZHALTER = [
  ["{absender_name}", "Name der Person"], ["{absender_rolle}", "Funktion aus dem Profil"],
  ["{absender_telefon}", "Telefon aus dem Profil"], ["{absender_mail}", "E-Mail der Person"],
  ["{firma_name}", "Firmenname"], ["{firma_marke}", "Markenname des Standorts"],
  ["{firma_strasse}", "Straße"], ["{firma_plz_ort}", "PLZ und Ort"],
  ["{firma_hrb}", "HRB und Registergericht"], ["{firma_geschaeftsfuehrer}", "Geschäftsführer"],
  ["{firma_telefon}", "Telefon der Firma"], ["{firma_mail}", "E-Mail der Firma"],
  ["{firma_web}", "Webadresse"],
];
// Eigene Signatur schlägt Vorlage. Ohne beides bleibt der Text leer - lieber keine Signatur als
// eine mit falschen Firmendaten.
function epSignatur(person, opt) {
  const p = person || {}, o = opt || {};
  const eigene = String(p.signatur || "").trim();
  const vorlage = eigene || epEinst("signatur_vorlage", "");
  if (!vorlage) return "";
  const f = epFirma(o.standort || epEinst("standort_standard", "musterstadt")) || {};
  const werte = {
    "{absender_name}": p.name || "",
    "{absender_rolle}": p.funktion || o.rolle || "",
    "{absender_telefon}": p.telefon || f.telefon || "",
    "{absender_mail}": p.email || f.email || "",
    "{firma_name}": f.firma_name || "",
    "{firma_marke}": f.marken_name || f.firma_name || "",
    "{firma_strasse}": f.strasse || "",
    "{firma_plz_ort}": [f.plz, f.ort].filter(Boolean).join(" "),
    "{firma_hrb}": [f.hrb, f.registergericht].filter(Boolean).join(" "),
    "{firma_geschaeftsfuehrer}": f.geschaeftsfuehrer || "",
    "{firma_telefon}": f.telefon || "",
    "{firma_mail}": f.email || "",
    "{firma_web}": f.web || "",
  };
  let t = String(vorlage);
  Object.keys(werte).forEach((k) => { t = t.split(k).join(werte[k]); });
  return t;
}

