function EinstVertragsvorlagen({ user }) {
  const [zeilen, setZeilen] = useState([]);
  const [laedt, setLaedt] = useState(true);
  const [meldung, setMeldung] = useState("");
  const [fehler, setFehler] = useState("");
  const [beschaeftigt, setBeschaeftigt] = useState("");
  const darfPflegen = hatRecht(user, "admin");
  const [vorgabenEntwurf, setVorgabenEntwurf] = useState({});
  const [markiert, setMarkiert] = useState(null);
  // Nur die Felder DIESER Art werden geschrieben. Ein Wert, der zu
  // einer anderen Art gehoert, weist die Datenbank ohnehin ab — aber
  // es waere ein Fehler, der erst dort auffaellt.
  const werteSichern = async (art, zeile) => {
    setFehler(""); setMeldung(""); setBeschaeftigt("werte-" + art);
    try {
      const neu = {};
      for (const [feld, , ersatz] of (IMMO_VORLAGE_FELDER[art] || [])) {
        const schluessel = art + "." + feld;
        const w = String(vorgabenEntwurf[schluessel] !== undefined
          ? vorgabenEntwurf[schluessel]
          : ((zeile.vorgaben && zeile.vorgaben[feld]) || immoVorgabe(art, feld, ersatz))).trim();
        if (w) neu[feld] = w;
      }
      const { error } = await window._sb.from("vertragsvorlagen")
        .update({ vorgaben: neu, geaendert_am: new Date().toISOString() }).eq("id", zeile.id);
      if (error) throw error;
      await logAction("update", "vertragsvorlage", zeile.id, art, neu);
      // Damit die Formulare sofort den neuen Wert sehen und nicht erst
      // nach dem naechsten Anmelden.
      try {
        const { data } = await window._sb.rpc("vorlage_vorgaben", {
          p_art: art, p_gesellschaft: window.IMMO_GESELLSCHAFT_ID || null });
        if (data) window.__immoVorgaben = { ...(window.__immoVorgaben || {}), [art]: data };
      } catch (_) { /* beim naechsten Start */ }
      setMeldung("Werte gespeichert.");
      await laden();
    } catch (f) {
      setFehler("Speichern fehlgeschlagen: " + (f.message || f));
    }
    setBeschaeftigt("");
  };
  const laden = async () => {
    setLaedt(true);
    try {
      const { data, error } = await window._sb.from("vertragsvorlagen")
        .select("*").order("art").order("version", { ascending: false });
      if (error) throw error;
      setZeilen(data || []);
    } catch (f) {
      setFehler("Vorlagen konnten nicht geladen werden: " + (f.message || f));
    }
    setLaedt(false);
  };
  useEffect(() => { laden(); }, []);
  const aktuelle = (art) => (zeilen.filter((z) => z.art === art && z.aktiv)[0] || null);
  const hochladen = async (art, datei) => {
    if (!datei) return;
    setFehler(""); setMeldung(""); setBeschaeftigt(art);
    try {
      const vorher = zeilen.filter((z) => z.art === art);
      const version = vorher.reduce((m, z) => Math.max(m, z.version || 0), 0) + 1;
      // Mandantenrelativ: die Speicher-Huelle stellt die Mandantenkennung
      // voran, die Richtlinie aus fork_09 prueft sie.
      const istPdf = /\.pdf$/i.test(datei.name || "");
      const endung = istPdf ? ".pdf" : ".docx";
      const pfad = "vorlagen/" + art + "/v" + version + "-" + Date.now() + endung;
      const { error: uErr } = await window._sb.storage.from("vertragsvorlagen")
        .upload(pfad, datei, { upsert: false,
          contentType: istPdf ? "application/pdf"
            : "application/vnd.openxmlformats-officedocument.wordprocessingml.document" });
      if (uErr) throw uErr;
      // Die neue Fassung gilt, die alten bleiben liegen.
      await window._sb.from("vertragsvorlagen").update({ aktiv: false }).eq("art", art);
      const vorher_aktiv = vorher.filter((z) => z.aktiv)[0] || vorher[0] || null;
      const { error: iErr } = await window._sb.from("vertragsvorlagen").insert({
        art, storage_pfad: pfad, dateiname: datei.name || "", version, aktiv: true,
        dateiformat: istPdf ? "pdf" : "docx",
        vorgaben: (vorher_aktiv && vorher_aktiv.vorgaben) || {},
        gesellschaft_id: window.IMMO_GESELLSCHAFT_ID || null,
        hochgeladen_von: window._currentUserId || null
      });
      if (iErr) throw iErr;
      await logAction("upload", "vertragsvorlage", art, datei.name || art, { version });
      setMeldung("Vorlage für „" + art + "“ gespeichert (Fassung " + version + ").");
      await laden();
    } catch (f) {
      setFehler("Hochladen fehlgeschlagen: " + (f.message || f));
    }
    setBeschaeftigt("");
  };
  if (laedt) return React.createElement("div", { style: { padding: 24, color: CI.muted } }, "Lade Vorlagen …");
  // Solange eine Vorlage markiert wird, tritt die Liste zurueck. Zwei
  // Dinge nebeneinander waeren auf einem schmalen Bildschirm keines.
  if (markiert) return React.createElement(VorlagenMarkierung, {
    vorlage: markiert, user, onSchliessen: () => { setMarkiert(null); laden(); } });
  return React.createElement("div", null,
    React.createElement("div", { style: { fontSize: 13, color: CI.muted, marginBottom: 16, lineHeight: 1.6 } },
      "Hier hinterlegst du deine eigenen Word-Vorlagen. Sie werden verwendet, sobald sie da sind; ",
      "eine neue Fassung ersetzt die alte nicht, sie überholt sie — ältere bleiben nachvollziehbar liegen."),
    React.createElement("div", { style: { padding: "12px 14px", background: `${CI.gold}18`,
      borderLeft: `3px solid ${CI.gold}`, fontSize: 12.5, color: CI.blau, lineHeight: 1.5, marginBottom: 20 } },
      React.createElement("strong", null, "Rechtlicher Hinweis: "),
      "Diese Anwendung prüft die hochgeladenen Texte nicht und macht keine Aussage darüber, "
      + "ob sie rechtssicher sind. Die inhaltliche und rechtliche Verantwortung für jede Vorlage "
      + "liegt bei dir; eine anwaltliche Prüfung ist erforderlich."),
    React.createElement(ErrorBox, null, fehler),
    React.createElement(SuccessBox, null, meldung),
    !darfPflegen ? React.createElement("div", { style: { fontSize: 12.5, color: CI.muted, marginBottom: 16 } },
      "Zum Ändern fehlt dir das Recht „Admin-Bereich“ — du siehst hier nur, was hinterlegt ist.") : null,
    React.createElement("div", { style: { display: "grid",
      gridTemplateColumns: "repeat(auto-fit, minmax(min(300px,100%), 1fr))", gap: 12 } },
      IMMO_VERTRAGSARTEN.map(([art, label, hinweis]) => {
        const jetzt = aktuelle(art);
        return React.createElement("div", { key: art, "data-vertragsart": art,
          style: { border: `1px solid ${CI.border}`, padding: 16, background: "#fff" } },
          React.createElement("div", { style: { fontSize: 14, fontWeight: 700, color: CI.blau } }, label),
          React.createElement("div", { style: { fontSize: 12, color: CI.muted, marginTop: 6, lineHeight: 1.5 } }, hinweis),
          React.createElement("div", { style: { fontSize: 12.5, marginTop: 12,
            color: jetzt ? CI.blau : CI.muted } },
            jetzt ? ("Fassung " + jetzt.version + (jetzt.dateiname ? " — " + jetzt.dateiname : ""))
                  : "Noch keine Vorlage hinterlegt."),
          jetzt ? React.createElement("button", {
            onClick: () => setMarkiert(jetzt), "data-markieren": art,
            style: { ...secondaryBtn, padding: "7px 14px", fontSize: 12.5, marginTop: 10 } },
            darfPflegen ? "Felder markieren" : "Markierungen ansehen") : null,
          (jetzt && (IMMO_VORLAGE_FELDER[art] || []).length) ? React.createElement("div",
            { style: { marginTop: 12, paddingTop: 12, borderTop: `1px solid ${CI.border}` } },
            React.createElement("div", { style: { fontSize: 11, color: CI.gold, letterSpacing: "0.12em",
              textTransform: "uppercase", fontWeight: 600, marginBottom: 8 } }, "Werte zu diesem Text"),
            IMMO_VORLAGE_FELDER[art].map(([feld, beschriftung, ersatz, auswahl]) => {
              const schluessel = art + "." + feld;
              const wert = vorgabenEntwurf[schluessel] !== undefined
                ? vorgabenEntwurf[schluessel]
                : ((jetzt.vorgaben && jetzt.vorgaben[feld]) || immoVorgabe(art, feld, ersatz));
              return React.createElement("div", { key: feld, style: { marginBottom: 8 } },
                React.createElement("label", { style: labelStyle }, beschriftung),
                auswahl
                  ? React.createElement("select", { style: inputStyle, value: wert,
                      "data-vorlagenwert": schluessel, disabled: !darfPflegen,
                      onChange: (ev) => setVorgabenEntwurf((a) => ({ ...a, [schluessel]: ev.target.value })) },
                      auswahl.map(([w, l]) => React.createElement("option", { key: w, value: w }, l)))
                  : React.createElement("input", { style: inputStyle, value: wert,
                      "data-vorlagenwert": schluessel, disabled: !darfPflegen,
                      onChange: (ev) => setVorgabenEntwurf((a) => ({ ...a, [schluessel]: ev.target.value })) }));
            }),
            darfPflegen ? React.createElement("button", {
              onClick: () => werteSichern(art, jetzt), disabled: beschaeftigt === "werte-" + art,
              style: { ...secondaryBtn, padding: "7px 14px", fontSize: 12.5, marginTop: 4 } },
              beschaeftigt === "werte-" + art ? "Speichert …" : "Werte speichern") : null,
            React.createElement("div", { style: { fontSize: 11, color: CI.muted, marginTop: 8, lineHeight: 1.5 } },
              "Diese Werte werden in neue Vorgänge übernommen. Sie müssen zu dem passen, ",
              "was im Text dieser Vorlage steht.")) : null,
          darfPflegen ? React.createElement("label", { style: { ...secondaryBtn, display: "inline-flex",
            marginTop: 12, cursor: beschaeftigt === art ? "wait" : "pointer",
            opacity: beschaeftigt === art ? .6 : 1 } },
            beschaeftigt === art ? "Lädt …" : (jetzt ? "Neue Fassung hochladen" : "Vorlage hochladen"),
            React.createElement("input", { type: "file", accept: ".docx,.pdf", style: { display: "none" },
              disabled: beschaeftigt === art,
              onChange: (ev) => { const d = ev.target.files && ev.target.files[0];
                ev.target.value = ""; hochladen(art, d); } })) : null);
      })));
}

