async function epExposeAbgerufenFiltern(liste) {
  const selbst = (f) => !!(f.bestaetigt_am || f.heruntergeladen_am || f.letzter_download_am || (Number(f.downloads) || 0) > 0);
  let rest = (liste || []).filter((f) => !selbst(f));
  const ids = [...new Set(rest.map((f) => f.immobilie_id).filter(Boolean))];
  if (!ids.length || !window._sb) return rest;
  try {
    const { data, error } = await window._sb.from("expose_abgerufen_schluessel").select("email, kontakt_id, immobilie_id").in("immobilie_id", ids);
    if (error) throw error;
    const menge = new Set();
    for (const z of data || []) {
      if (z.email) menge.add("e|" + String(z.email).trim().toLowerCase() + "|" + z.immobilie_id);
      if (z.kontakt_id) menge.add("k|" + z.kontakt_id + "|" + z.immobilie_id);
    }
    rest = rest.filter((f) => !(f.email && menge.has("e|" + String(f.email).trim().toLowerCase() + "|" + f.immobilie_id))
      && !(f.kontakt_id && menge.has("k|" + f.kontakt_id + "|" + f.immobilie_id)));
  } catch (x) { console.warn("Exposé-Abrufe:", x.message || x) }
  return rest;
}
