  const pfad = await epDateiAmObjektAblegen({ immobilieId: eintrag.immobilie_id, name, mimeType: mime, blob, quelle: "onedrive", kategorie: "dokument", doktyp, userId: window._currentUserId || null, oeffentlich: false, webFassung: false });
  const { data: neu, error: e2 } = await window._sb.from("immobilie_datei").update({ interessenten_freigabe: true, onedrive_drive_id: driveId || null, onedrive_item_id: itemId }).eq("storage_path", pfad).select("id").maybeSingle();
