    const fG = r.flaeche || epAbFlaeche(poly), sG = epAbSchwerpunkt(poly);
    const verhaeltnis = fE / Math.max(0.01, fG); if (verhaeltnis < 0.5 || verhaeltnis > 2) return;   // ganz andere Größe: kein Kandidat
